using UnityEngine;
using UnityEngine.InputSystem;
namespace LWS.TruckSports {
public sealed class SportsFrontEnd:SportsMenuView {
 public SportsCatalogue catalogue;
 protected override void Start(){base.Start();SportsNavigation.EnterCollection();Show(SportsNavigation.OpenSelection?1:0);SportsNavigation.OpenSelection=false;}
 public override void Action(string key){base.Action(key);if(key=="catalogueprev"||key=="cataloguenext"){catalogue.Step(key=="catalogueprev"?-1:1);Focus();return;}switch(key){case "fishing":SportsNavigation.LoadSport(SportsNavigation.Fishing);break;case "bungee":SportsNavigation.LoadSport(SportsNavigation.Bungee);break;case "bog":SportsNavigation.LoadSport(SportsNavigation.Bog);break;case "buzkashi":SportsNavigation.LoadSport(SportsNavigation.Buzkashi);break;case "swing":SportsNavigation.LoadSport(SportsNavigation.Swing);break;case "parking":SportsNavigation.LoadSport(SportsNavigation.Parking);break;case "wife":SportsNavigation.LoadSport(SportsNavigation.Wife);break;case "mattress":SportsNavigation.LoadSport(SportsNavigation.Mattress);break;case "minefield":SportsNavigation.LoadSport(SportsNavigation.Minefield);break;case "play":Show(1);break;case "practice":SportsNavigation.BilliardsPractice=true;SportsNavigation.LoadSport(SportsNavigation.Billiards);break;case "billiards":SportsNavigation.BilliardsPractice=false;SportsNavigation.LoadSport(SportsNavigation.Billiards);break;case "dock":SportsNavigation.LoadSport(SportsNavigation.Dock);break;case "terrier":SportsNavigation.LoadSport(SportsNavigation.Terrier);break;case "keepawayfp":SportsNavigation.LoadSport(SportsNavigation.KeepawayCab);break;case "keepaway":SportsNavigation.LoadSport(SportsNavigation.Keepaway);break;case "curling":SportsNavigation.LoadSport(SportsNavigation.Curling);break;case "basejump":SportsNavigation.LoadSport(SportsNavigation.BaseJump);break;case "cheese":SportsNavigation.LoadSport(SportsNavigation.Cheese);break;case "cornhole":SportsNavigation.LoadSport(SportsNavigation.Cornhole);break;case "wallball":SportsNavigation.LoadSport(SportsNavigation.Wallball);break;case "airhockey":SportsNavigation.LoadSport(SportsNavigation.AirHockey);break;case "bowling":SportsNavigation.LoadSport(SportsNavigation.Bowling);break;case "hockey":SportsNavigation.LoadSport(SportsNavigation.Hockey);break;case "help":Show(2);break;case "settings":SettingsText();Show(3);break;case "back":Show(0);break;case "quit":Application.Quit();break;}}
 protected override void Update(){base.Update();bool back=SportsDeviceInput.KeyDown(Key.Escape);foreach(var p in Gamepad.all)back|=menuInput.Down(p,8);if(back&&Page!=0)Show(0);}
}
}
